  ?subject ?p ?o.
  FILTER(CONTAINS(STR(?subject), "chiller") || CONTAINS(STR(?subject), "ahu"))
  ?subject rdf:type ?type.
}
LIMIT 50

SELECT ?type (COUNT(?s) as ?n) WHERE {
  ?s rdf:type ?type.
} GROUP BY ?type ORDER BY DESC(?n) LIMIT 60

SELECT ?subject WHERE {
  ?subject rdf:type brick:AHU.
  ?subject rdfs:label ?lbl .
  FILTER(CONTAINS(STR(?lbl), "01"))
}
LIMIT 50

SELECT ?subject ?type WHERE {
  ?subject rdf:type ?type.
  FILTER(CONTAINS(STR(?subject), "AHU01") || CONTAINS(STR(?subject), "Ahhu01") || CONTAINS(STR(?subject), "ahu_01"))
}
LIMIT 50

SELECT ?subject ?type ?ts WHERE {
  ?subject rdf:type ?type.
  FILTER(
    (CONTAINS(STR(?type), "Electric_Power") ||
     CONTAINS(STR(?type), "Power_Sensor")) &&
    (CONTAINS(STR(?subject), "Chiller01") || CONTAINS(STR(?subject), "AHU01"))
  ).
  ?subject ref:hasTimeseriesId ?ts.
}
LIMIT 50

SELECT ?s ?type ?tsref WHERE {
  ?s rdf:type ?type.
  FILTER(CONTAINS(STR(?s), "Chiller01") && (CONTAINS(STR(?type), "Power") || CONTAINS(STR(?type), "Voltage") || CONTAINS(STR(?type), "Current"))).
  ?s ref:hasExternalReference ?tsref.
}
LIMIT 20

SELECT ?s ?type ?tsref WHERE {
  ?s rdf:type ?type.
  FILTER(CONTAINS(STR(?s), "AHU01") && (CONTAINS(STR(?type), "Power"))).
